def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    # Check for early defection (before round 50)
    early_def = False
    limit = min(n, 50)
    for i in range(limit):
        if history[i][1] == 'D':
            early_def = True
            break

    if early_def:
        return 'C'

    if n >= 97:
        return 'D'

    if history[-1][1] == 'D':
        return 'D'

    return 'C'
